(() => {
  const label = Array.from(document.querySelectorAll('label')).find(l => l.textContent.includes('Visualizations'));
  let parent = label;
  for (let i = 0; i < 5; i++) {
    if (parent.parentElement) parent = parent.parentElement;
    const opts = parent.querySelectorAll('[role="option"], [role="listitem"], [class*="option"], [class*="item"]');
    if (opts.length > 3) {
      return Array.from(opts).map(o => o.textContent.trim().substring(0,40) + ' | ' + (o.getAttribute('aria-label')||'') + ' | ' + o.className.substring(0,50));
    }
  }
  return 'no options found';
})()

(() => {
  const label = Array.from(document.querySelectorAll('label')).find(l => l.textContent.includes('Visualizations'));
  if (!label) return 'no label';
  let parent = label;
  for (let i = 0; i < 6; i++) {
    parent = parent.parentElement;
    if (!parent) return 'ran out';
    const txt = parent.textContent.trim();
    if (txt.length > 100) return 'level ' + i + ' | ' + txt.substring(0, 600);
  }
  return 'nothing big';
})()

(() => {
  const label = Array.from(document.querySelectorAll('label')).find(l => l.textContent.includes('Visualizations'));
  let parent = label;
  for (let i = 0; i < 6; i++) {
    parent = parent.parentElement;
    if (parent && parent.textContent.includes('Supports markdown and html content')) {
      // find the Text option element
      const items = Array.from(parent.querySelectorAll('*')).filter(el => el.children.length === 0 && el.textContent.trim() === 'Text');
      if (items.length) {
        const target = items[0].closest('[role="option"], [role="button"], button, div[class*="item"], div[class*="option"]') || items[0].parentElement;
        return 'found: ' + target.tagName + ' | ' + target.className.substring(0,60) + ' | rect: ' + JSON.stringify(target.getBoundingClientRect());
      }
    }
  }
  return 'not found';
})()

